import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract_packages(data):
    result = {}
    for project in data.get('projects', []):
        name = project['path'].split('/')[-1]
        pkgs = {}
        for fw in project.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], fw['framework'])
                pkgs[key] = pkg['resolvedVersion']
        result[name] = pkgs
    return result

b = extract_packages(baseline)
a = extract_packages(after)

print('=== CHANGES ===')
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            print(f'  {proj}: {key[0]} ({key[1]}): {bv} -> {av}')

print()
print('=== UNCHANGED (sample) ===')
count = 0
for proj in sorted(b.keys()):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(bp.keys()):
        if bp.get(key) == ap.get(key):
            count += 1
print(f'  {count} package-framework pairs unchanged')
